<?php
namespace App\Filament\Resources;use App\Enums\ProductType;use App\Filament\Resources\ProductResource\Pages;use App\Models\ProductCategory;use Filament\Resources\Forms\Components;use Filament\Resources\Forms\Form;use Filament\Resources\Resource;use Filament\Resources\Tables\Columns;use Filament\Resources\Tables\Filter;use Filament\Resources\Tables\RecordActions;use Filament\Resources\Tables\Table;
class ProductResource extends Resource{public static $icon='heroicon-o-shopping-bag';public static $label='Sản phẩm';public static $navigationLabel='Sản phẩm';public static $navigationSort=50;public static function typeLabels(){return array_combine(ProductType::values(),['Lõi lọc','Linh kiện','Máy','Dịch vụ','Khác']);}public static function form(Form $f){return$f->schema([Components\FileUpload::make('image_path')->label('Ảnh sản phẩm')->image()->disk('public')->directory('products')->maxSize(5120)->imagePreviewHeight(180),Components\Select::make('category_id')->label('Danh mục')->options(ProductCategory::pluck('name','id')->toArray()),Components\TextInput::make('sku')->label('SKU')->required()->unique(static::getModel(),'sku',true),Components\TextInput::make('name')->label('Tên')->required(),Components\Select::make('product_type')->label('Loại')->options(static::typeLabels())->required(),Components\TextInput::make('unit')->label('Đơn vị')->default('piece')->required(),Components\TextInput::make('low_stock_threshold')->label('Mức cảnh báo tồn thấp')->numeric()->default(0),Components\TextInput::make('cost_price')->label('Giá vốn (VND)')->numeric()->default(0),Components\TextInput::make('selling_price')->label('Giá bán (VND)')->numeric()->default(0),Components\TextInput::make('replacement_months')->label('Chu kỳ thay (tháng)')->numeric(),Components\TextInput::make('brand_name')->label('Thương hiệu'),Components\Textarea::make('description')->label('Mô tả'),Components\TagsInput::make('compatible_models')->label('Model tương thích'),Components\Select::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','inactive'=>'Ngừng'])->default('active')]);}public static function table(Table $t){return$t->columns([Columns\Image::make('image_path')->label('Ảnh')->disk('public')->size(52),Columns\Text::make('sku')->label('SKU')->primary()->searchable()->sortable(),Columns\Text::make('name')->label('Tên')->searchable(),Columns\Text::make('category.name')->label('Danh mục'),Columns\Text::make('product_type')->label('Loại')->getValueUsing(fn($record)=>(string)$record->product_type)->options(static::typeLabels()),Columns\Text::make('stock_quantity')->label('Tồn kho')->sortable(),Columns\Text::make('low_stock_threshold')->label('Cảnh báo'),Columns\Text::make('cost_price')->label('Giá vốn')->currency('',',','.',0),Columns\Text::make('selling_price')->label('Giá bán')->currency('',',','.',0),Columns\Text::make('replacement_months')->label('Chu kỳ'),Columns\Text::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','inactive'=>'Ngừng'])])->filters([Filter::make('active',fn($q)=>$q->where('status','active'))->label('Đang bán'),Filter::make('filters',fn($q)=>$q->where('product_type','filter'))->label('Lõi lọc'),Filter::make('low_stock',fn($q)=>$q->whereColumn('stock_quantity','<=','low_stock_threshold'))->label('Sắp hết hàng')])->pushRecordActions([RecordActions\Link::make('inventory')->label('Quản lý kho')->url(fn($record)=>static::generateUrl('inventory',['record'=>$record]))]);}public static function routes(){return[Pages\ListProducts::routeTo('/','index'),Pages\CreateProduct::routeTo('/create','create'),Pages\EditProduct::routeTo('/{record}/edit','edit'),Pages\ProductInventory::routeTo('/{record}/inventory','inventory')];}}
